select 
  from sdsorder.u_o_order_${tableSuffix}
 where shop_code = #{query.shopCode}
 and ordercode like concat('%', #{query.orderCode}, '%')
 and orderstate = #{query.orderState}
 and paystatus = #{query.payStatus}
 and shopcode = #{query.shopStoreCode}
 and staffcode = #{query.staffCode}



     and staffcode in
      #{staff}

     and 1 = 0



 and buyercode = #{query.buyerCode}
 and buyername like concat('%', #{query.buyerName}, '%')
 and platcode = #{query.platCode}
 and platorderid = #{query.platOrderId}
 and receiveperson like concat('%', #{query.receivePerson}, '%')
 and createtime >= #{query.beginTime}

 and createtime < date_add(#{query.endTime}, interval 1 day)
 order by createtime desc, ordercode desc

select 
  from sdsorder.u_o_order_${tableSuffix}
 where shop_code = #{shopCode}
   and orderstate in
   #{state}
 order by field(orderstate, #{state}),
          createtime desc, ordercode desc

select 
  from sdsorder.u_o_order_${tableSuffix}
 where shop_code = #{shopCode}
   and ordercode in
   #{code}
 order by createtime desc, ordercode desc

select 
  from sdsorder.u_o_order_${tableSuffix}
 where shop_code = #{shopCode}
   and orderstate not in
   #{state}
   and coalesce(paidamount, 0) < coalesce(totalamount, 0)
 order by createtime desc, ordercode desc

select 
  from sdsorder.u_o_order_${tableSuffix}
 where shop_code = #{shopCode}
   and orderstate not in
